import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { resolve } from "node:path";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

const fileHashes = new Map<string, string>();

function normalizeRawPath(rawPath: string): string {
	return rawPath.startsWith("@") ? rawPath.slice(1) : rawPath;
}

export function clearUnchangedFileCache(): void {
	fileHashes.clear();
}

export function registerUnchangedFileCacheResetHandlers(pi: ExtensionAPI): void {
	pi.on("session_start", clearUnchangedFileCache);
	pi.on("session_compact", clearUnchangedFileCache);
	pi.on("session_tree", clearUnchangedFileCache);
}

export function resolveTrackedFilePath(cwd: string, rawPath: string): string {
	const path = normalizeRawPath(rawPath);
	return path.startsWith("~/") ? resolve(homedir(), path.slice(2)) : resolve(cwd, path);
}

export function formatUnchangedFileMessage(rawPath: string): string {
	return `Wasted call — file unchanged since your last Read (${rawPath})`;
}

function rememberHash(absolutePath: string, content: string | Buffer): boolean {
	const nextHash = createHash("sha256").update(content).digest("hex");
	const previousHash = fileHashes.get(absolutePath);
	fileHashes.set(absolutePath, nextHash);
	return previousHash === nextHash;
}

export function rememberFileContent(cwd: string, rawPath: string, content: string | Buffer): boolean {
	const absolutePath = resolveTrackedFilePath(cwd, rawPath);
	return rememberHash(absolutePath, content);
}

export async function rememberFileFromDisk(cwd: string, rawPath: string): Promise<boolean | undefined> {
	const absolutePath = resolveTrackedFilePath(cwd, rawPath);
	try {
		const content = await readFile(absolutePath);
		return rememberHash(absolutePath, content);
	} catch {
		return undefined;
	}
}
/**
 * Wasted Read Extension — Prevents repeatedly sending unchanged file contents
 * to the LLM within its active context.
 *
 * Intercepts read-tool results via `tool_result` events so it coexists
 * with other extensions that wrap `read` (e.g., smart-truncation/index.ts).
 *
 * On the first full-file read (no offset/limit): the SHA-256 hash is
 * stored. On subsequent full-file reads of the same file:
 *   - If hash matches → "Wasted call — file unchanged since your last Read (path)"
 *   - If hash differs → cache updated, original result passes through.
 *
 * Reads with offset or limit are always passed through unchanged.
 *
 * The cache is in-memory only and resets when a session starts or its context
 * is compacted. No disk persistence.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import {
	formatUnchangedFileMessage,
	registerUnchangedFileCacheResetHandlers,
	rememberFileFromDisk,
} from "../shared/unchanged-file-cache";

export default function (pi: ExtensionAPI) {
	registerUnchangedFileCacheResetHandlers(pi);

	pi.on("tool_result", async (event, ctx) => {
		if (event.toolName !== "read") return;

		const rawPath = event.input?.path as string | undefined;
		if (!rawPath) return;

		const offset = (event.input as Record<string, unknown>).offset as number | undefined;
		const limit = (event.input as Record<string, unknown>).limit as number | undefined;

		if (offset !== undefined || limit !== undefined) return;

		const isUnchanged = await rememberFileFromDisk(ctx.cwd, rawPath);
		if (!isUnchanged) return;

		const details =
			event.details && typeof event.details === "object"
				? (event.details as Record<string, unknown>)
				: {};

		return {
			content: [
				{
					type: "text" as const,
					text: formatUnchangedFileMessage(rawPath),
				},
			],
			details: { ...details, wastedRead: true },
		};
	});
